type Props={data:WorkspaceData;onBack:()=>void;onChanged:()=>Promise<void>};
const lanes:PipelineLane[]=["design","review","approved","queued","running","analysis","completed","failed","legacy"];
const text=(value:unknown) => typeof value==="string" ? value : value==null ? "" : JSON.stringify(value,null,2);
const list=(value:string) => value.split(/[\n,]/).map((item)=>item.trim()).filter(Boolean);
const statusLabel=(value?:string) => ({draft:"草稿",prepared:"已准备",planned:"已规划",ready_to_start:"等待启动",execution_completed:"执行结束",analysis_pending:"待分析",failed:"失败",pending_review:"待审核",changes_requested:"需修改",approved:"已批准",completed:"已完成"} as Record<string,string>)[value||""] || value || "未登记";
const formatTimestamp=(value?:string)=>{if(!value)return "未记录";const date=new Date(value);return Number.isNaN(date.getTime())?value:date.toLocaleString("zh-CN",{dateStyle:"medium",timeStyle:"short"})};
const workspaceLabel=(workspace:ExperimentWorkspaceBinding,dashboard:ExperimentDashboard)=>{const server=dashboard.servers?.find(item=>item.id===workspace.server_id);return `${workspace.id} · ${workspace.label||"未命名"} → ${server?.label||server?.id||"Server 未绑定"}/${server?.ssh_host||"无 ssh_host"} · ${workspace.remote_repo||"remote_repo 未登记"}`};

const experimentFields=[["title","标题"],["objective","研究目标"],["workspace_id","执行 Workspace"],["code_repository_workspace_id","代码仓库连接"],["constraints","约束"],["evidence_refs","证据引用"],["hypothesis","假设"],["success_criteria","成功标准"],["failure_criteria","失败标准"]] as const;
const runCreateFields=[["id","Run ID"],["variant","变体名称"],["group_id","职责分组"],["research_question","研究问题"],["purpose","目的"],["method_plan","方法（干预、对照、指标与判定规则）"],["implementation_details","详细实现细节（数据、代码、环境）"],["hypothesis","假设（历史）"],["metric_plan","指标计划（历史）"],["data_definition","数据定义（历史）"],["variables_controls","变量与对照（历史）"],["workspace_id","Workspace"]] as const;
const experimentCoreFields=experimentFields.filter(([key])=>["title","objective","workspace_id","code_repository_workspace_id"].includes(key));
const experimentAdvancedFields=experimentFields.filter(([key])=>!["title","objective","workspace_id","code_repository_workspace_id"].includes(key));
const runCoreKeys=["id","variant","research_question","purpose","method_plan","implementation_details"];
const runCoreFields=runCreateFields.filter(([key])=>runCoreKeys.includes(key));
const runAdvancedFields=runCreateFields.filter(([key])=>!runCoreKeys.includes(key));
const runSections=[
  ["研究设计",[["research_question","研究问题"],["purpose","目的"]]],
  ["方法",[["method_plan","方法（干预 · 对照 · 指标与判定规则）"]]],
  ["实现与运行",[["implementation_details","详细实现细节（数据定义与规模、代码结构、环境）"],["implementation_ref","实现引用"],["workspace_id","Workspace"],["command","命令"],["git_commit","Git commit"],["artifact_dir","产物目录"],["output_dir","输出目录（绝对路径）"],["log_path","日志路径"],["metrics_path","指标文件路径（绝对路径）"]]],
  ["结果",[["result_summary","结果摘要"],["result_analysis","结果分析"],["key_results","关键结果"],["metric_observations","已注册指标观测"],["auxiliary_metric_observations","辅助指标（尚未注册）"],["limitations","限制"],["artifacts","产物"],["audit_paths","审计路径"]]],
  ["历史字段（可选；有内容会自动归入方法与实现细节小节）",[["hypothesis","假设"],["necessity","必要性"],["evidence_basis","证据基础"],["data_definition","数据定义"],["data_scale","数据规模"],["variables_controls","变量与对照"],["metric_plan","指标计划"],["metric_definition","指标定义"],["integrity_gates","完整性门槛"],["acceptance_criteria","验收判定"],["architecture_plan","架构方案"],["implementation_summary","实现摘要"],["model_config","模型配置"],["expected_outcome","预期特征"],["conclusion_scope","结论范围"],["claim_boundary","Claim 边界"],["project_dir","项目目录"]]],
] as Array<[string,Array<[keyof Run,string]>]>;
const runEditKeys=runSections.flatMap(([,fields])=>fields.map(([key])=>key));
const jsonKeys=new Set<keyof Run>(["key_results","metric_observations","auxiliary_metric_observations","implementation_ref"]);

type ExperimentLocation={experimentId:string;runId:string;tab:"runs"|"pipeline"|"stewards"|"documents"};
function rememberedExperimentLocation(projectPath:string):ExperimentLocation{
  try{const value=JSON.parse(window.localStorage.getItem(`survey-v2-experiment-location:${projectPath}`)||"{}");return {experimentId:typeof value.experimentId==="string"?value.experimentId:"",runId:typeof value.runId==="string"?value.runId:"",tab:["runs","pipeline","stewards","documents"].includes(value.tab)?value.tab:"runs"}}catch{return {experimentId:"",runId:"",tab:"runs"}}
}

export function ExperimentWorkspace({data,onBack,onChanged}:Props){
  const dashboard=data.dashboard;
  const remembered=rememberedExperimentLocation(data.project.path);
  const [experimentId,setExperimentId]=useState(()=>dashboard.experiments.some(item=>item.id===remembered.experimentId&&!item.archived_at)?remembered.experimentId:dashboard.experiments.find(item=>!item.archived_at)?.id||"");
  const [runId,setRunId]=useState(()=>dashboard.runs.some(item=>item.id===remembered.runId&&!item.archived_at)?remembered.runId:"");
  const [tab,setTab]=useState<ExperimentLocation["tab"]>(remembered.tab);
  const [creatingExperiment,setCreatingExperiment]=useState(false);
  const [editingExperiment,setEditingExperiment]=useState(false);
  const [creatingRun,setCreatingRun]=useState(false);
  const [grouping,setGrouping]=useState(false);
  const [aiGrouping,setAiGrouping]=useState(false);
  const [error,setError]=useState("");
  const [saving,setSaving]=useState(false);
  const [aiOpen,setAiOpen]=useState(false);
  const [environmentOpen,setEnvironmentOpen]=useState(false);
  const [assigningEnvironment,setAssigningEnvironment]=useState(false);
  const [archiveOpen,setArchiveOpen]=useState(false);
  const [localDashboard,setLocalDashboard]=useState<ExperimentDashboard|null>(null);
  const effectiveDashboard=localDashboard||dashboard;
  const activeExperiments=effectiveDashboard.experiments.filter(item=>!item.archived_at);
  const experiment=activeExperiments.find((item)=>item.id===experimentId)||activeExperiments[0];
  const runs=effectiveDashboard.runs.filter((run)=>run.experiment_id===experiment?.id&&!run.archived_at);
  const selectedRun=effectiveDashboard.runs.find((run)=>run.id===runId&&run.experiment_id===experiment?.id&&!run.archived_at);
  const workspace=effectiveDashboard.workspaces?.find((item)=>item.id===experiment?.workspace_id);const boundServer=effectiveDashboard.servers?.find((item)=>item.id===workspace?.server_id);

  useEffect(()=>{window.localStorage.setItem(`survey-v2-experiment-location:${data.project.path}`,JSON.stringify({experimentId:experiment?.id||experimentId,runId:selectedRun?.id||"",tab}))},[data.project.path,experiment?.id,experimentId,selectedRun?.id,tab]);
  useEffect(()=>{if(experiment&&experiment.id!==experimentId)setExperimentId(experiment.id);if(runId&&!selectedRun)setRunId("")},[experiment?.id,experimentId,runId,selectedRun]);

  const mutate=async(work:()=>Promise<unknown>)=>{setSaving(true);setError("");try{const result=await work();if(result&&typeof result==="object"&&"dashboard" in result)setLocalDashboard((result as {dashboard:ExperimentDashboard}).dashboard);onChanged().then(()=>setLocalDashboard(null)).catch((reason)=>setError(`操作已保存，但全局刷新失败：${reason instanceof Error?reason.message:String(reason)}`));return true}catch(reason){setError(reason instanceof ApiError&&reason.reason==="registry_version_conflict"?"内容已被其他写入修改，请刷新后重试":reason instanceof Error?reason.message:String(reason));return false}finally{setSaving(false)}};

  if(selectedRun&&experiment)return <RunDetail run={selectedRun} experiment={experiment} dashboard={effectiveDashboard} projectPath={data.project.path} saving={saving} error={error} setError={setError} mutate={mutate} onChanged={onChanged} onBack={()=>setRunId("")}/>;

  return <div className="experiment-workspace-page">
    {aiOpen&&experiment&&<AiDiscussionPanel targetType="experiment" targetId={experiment.id} targetLabel={`${experiment.id} · ${experiment.title}`} projectPath={data.project.path} runs={runs} onClose={()=>setAiOpen(false)}/>}
    {environmentOpen&&<EnvironmentBindingsPanel projectPath={data.project.path} onChanged={onChanged} onClose={()=>setEnvironmentOpen(false)}/>}
    {archiveOpen&&<ExperimentArchiveManager projectPath={data.project.path} dashboard={effectiveDashboard} onDashboard={value=>{setLocalDashboard(value);const current=value.experiments.find(item=>item.id===experimentId);if(current?.archived_at){setExperimentId(value.experiments.find(item=>!item.archived_at)?.id||"");setRunId("")}}} onChanged={onChanged} onClose={()=>setArchiveOpen(false)}/>}
    <div className="experiment-page-heading"><div><button className="back-button" onClick={onBack}><ArrowLeft size={15}/>研究总览</button><div className="eyebrow">Experiment Operations</div><h1>实验</h1><p>Experiment 管研究目标和代码准备；Run 只追踪一次受控运行、监控证据与结果。</p></div><div className="experiment-heading-actions"><button className="secondary-button" onClick={()=>setArchiveOpen(true)}>失效记录</button><button className="primary-button" onClick={()=>setCreatingExperiment(true)}><FlaskConical size={15}/>新建实验</button></div></div>
    {error&&<div className="detail-error">{error}</div>}
    {creatingExperiment&&<ExperimentForm dashboard={effectiveDashboard} saving={saving} onCancel={()=>setCreatingExperiment(false)} onSave={(fields)=>void mutate(async()=>{const result=await createV2Experiment(data.project.path,fields);setExperimentId(result.experiment.id);setCreatingExperiment(false);return result})}/>}
    <div className="experiment-v2-layout"><aside className="experiment-list-panel"><div className="experiment-list-head"><h2>Experiments</h2><span>{activeExperiments.length}</span></div><div className="experiment-list-items">{activeExperiments.map((item)=><button key={item.id} className={experiment?.id===item.id?"selected":""} onClick={()=>{setExperimentId(item.id);setRunId("")}}><span className="experiment-list-id">{item.id}</span><span><strong>{item.title}</strong><small>{statusLabel(item.status)} · {effectiveDashboard.runs.filter((run)=>run.experiment_id===item.id&&!run.archived_at).length} Runs</small></span></button>)}</div></aside>
      <main className="experiment-v2-main">{experiment?<><header className="experiment-v2-header"><div><div className="experiment-meta"><code>{experiment.id}</code><span>{statusLabel(experiment.status)}</span><span>{experiment.workflow_stage||"draft"}</span></div><h2>{experiment.title}</h2><p>{experiment.objective}</p><div className="experiment-binding-line"><strong>{workspace?.id||experiment.workspace_id||"未配置"} · {workspace?.label||"Workspace label 未登记"}</strong><span>{boundServer?`${boundServer.label||boundServer.id}/${boundServer.ssh_host||"无 ssh_host"}`:"Server 未绑定"} · {workspace?.remote_repo||"remote_repo 未登记"}</span></div><small>来源/证据：{text(experiment.evidence_refs)||"未登记"}</small><div className="metric-definition-summary"><strong>指标定义</strong>{(experiment.metric_definitions||[]).length?(experiment.metric_definitions||[]).map((metric)=><span key={String(metric.id)}><code>{String(metric.id)}</code> {String(metric.name||"")} · {String(metric.formula||"未登记公式")}</span>):<span>尚未登记；可在后续 Experiment 治理中补充，不阻塞本轮 Run 研究设计。</span>}</div></div><div className="experiment-header-actions"><button className="secondary-button" onClick={()=>setAiOpen(true)}><MessagesSquare size={14}/>与 AI 讨论</button><button className="primary-button" onClick={()=>setEditingExperiment(true)}><Pencil size={14}/>编辑实验方案</button><details className="compact-action-menu"><summary>环境设置</summary><button onClick={()=>setAssigningEnvironment(true)}><Server size={14}/>更换默认环境</button><button onClick={()=>setEnvironmentOpen(true)}>管理 Server / Workspace</button></details></div></header>
      <ExperimentHandoffPanel key={`${experiment.id}-${experiment.updated}`} experiment={experiment} saving={saving} onConfirm={(proposal,answers)=>void mutate(()=>confirmExperimentHandoff(data.project.path,experiment,proposal,answers))}/>
      {assigningEnvironment&&<EnvironmentAssignment title="更换 Experiment 默认环境" value={experiment.workspace_id||""} dashboard={effectiveDashboard} saving={saving} allowInherit={false} onCancel={()=>setAssigningEnvironment(false)} onSave={(workspaceId)=>void mutate(async()=>{const result=await updateV2Experiment(data.project.path,experiment.id,experiment.updated||"",{workspace_id:workspaceId});setAssigningEnvironment(false);return result})}/>}
      {editingExperiment&&<ExperimentForm experiment={experiment} dashboard={effectiveDashboard} saving={saving} onCancel={()=>setEditingExperiment(false)} onSave={(fields)=>void mutate(async()=>{const result=await updateV2Experiment(data.project.path,experiment.id,experiment.updated||"",fields);setEditingExperiment(false);return result})}/>}
      <div className="experiment-tabs"><button className={tab==="runs"?"active":""} onClick={()=>setTab("runs")}><Folder size={14}/>运行记录</button><button className={tab==="pipeline"?"active":""} onClick={()=>setTab("pipeline")}><Workflow size={14}/>状态看板</button><button className={tab==="stewards"?"active":""} onClick={()=>setTab("stewards")}><Activity size={14}/>后台监控</button><button className={tab==="documents"?"active":""} onClick={()=>setTab("documents")}><FileText size={14}/>文档</button></div>
      {tab==="runs"?<><div className="run-folder-actions"><button className="primary-button" onClick={()=>setCreatingRun(true)}><Plus size={14}/>新建 Run</button><details className="compact-action-menu"><summary>整理 Run</summary><button onClick={()=>{setAiGrouping(true);setGrouping(false)}}><Bot size={14}/>AI 辅助分组</button><button onClick={()=>{setGrouping(true);setAiGrouping(false)}}>手动管理分组</button></details></div>{creatingRun&&<RunCreateForm experiment={experiment} dashboard={effectiveDashboard} saving={saving} onCancel={()=>setCreatingRun(false)} onSave={(fields)=>void mutate(async()=>{const result=await createV2Run(data.project.path,experiment.id,fields);setCreatingRun(false);setRunId(result.run.id);return result})}/>} {aiGrouping&&<AiGroupingPanel experiment={experiment} runs={runs} projectPath={data.project.path} saving={saving} onCancel={()=>setAiGrouping(false)} onApplied={async()=>{setAiGrouping(false);await onChanged()}}/>}{grouping&&<GroupingForm experiment={experiment} runs={runs} saving={saving} onCancel={()=>setGrouping(false)} onSave={(groups,assignments)=>void mutate(async()=>{const result=await updateV2RunGrouping(data.project.path,experiment,groups,assignments);setGrouping(false);return result})}/>}<FolderBoard experiment={experiment} runs={runs} onOpen={setRunId}/></>:tab==="pipeline"?<PipelineBoard runs={runs} dashboard={effectiveDashboard} onOpen={setRunId}/>:tab==="documents"?<ExperimentDocumentsPanel key={`${data.project.path}:${experiment.id}`} projectPath={data.project.path} experimentId={experiment.id}/>:<StewardMonitor projectPath={data.project.path} experimentId={experiment.id} dashboard={effectiveDashboard} onOpen={(rid)=>{const target=effectiveDashboard.runs.find(item=>item.id===rid);if(target){setExperimentId(target.experiment_id);setRunId(rid)}}}/>}</>:<div className="question-detail-empty"><Beaker size={24}/><strong>创建或选择 Experiment</strong></div>}</main>
    </div>
  </div>
}

function ExperimentForm({experiment,dashboard,saving,onCancel,onSave}:{experiment?:Experiment;dashboard:ExperimentDashboard;saving:boolean;onCancel:()=>void;onSave:(fields:Partial<Experiment>)=>void}){
  const workspaces=dashboard.workspaces||[];
  const [draft,setDraft]=useState<Record<string,string>>(()=>Object.fromEntries(experimentFields.map(([key])=>[key,text(experiment?.[key])])));
  const metricLine=(experiment?.metric_definitions||[]).map((metric)=>[metric.id,metric.name,metric.formula,metric.meaning,metric.direction,metric.unit].map((value)=>String(value||"")).join(" | ")).join("\n");
  const [metrics,setMetrics]=useState(metricLine);const [metricError,setMetricError]=useState("");
  const blocked=!experiment&&!workspaces.length;
  const submit=()=>{const prior=new Map((experiment?.metric_definitions||[]).map((item)=>[String(item.id),item]));try{const definitions=metrics.split("\n").map((line)=>line.trim()).filter(Boolean).map((line,index)=>{const [id,name,formula,meaning,direction,unit]=line.split("|").map((part)=>part.trim());if(!id||!name||!formula)throw new Error(`第 ${index+1} 行必须包含 id、名称和公式`);return {...(prior.get(id)||{}),id,name,formula,meaning,direction,unit}});setMetricError("");onSave({...draft,code_repository_workspace_id:draft.code_repository_workspace_id||draft.workspace_id,evidence_refs:list(draft.evidence_refs),metric_definitions:definitions})}catch(reason){setMetricError(reason instanceof Error?reason.message:String(reason))}};
  return <section className="experiment-domain-form focused-create-form"><div className="domain-form-head"><div><strong>{experiment?"编辑实验方案":"创建实验"}</strong><small>先写清目标并选择执行环境和代码仓库，其余内容可以稍后补充。</small></div><button onClick={onCancel}><X size={14}/></button></div>{blocked&&<div className="detail-error">当前没有可用 Workspace；请先登记执行环境。</div>}{metricError&&<div className="detail-error">指标定义格式错误：{metricError}</div>}<div className="domain-form-grid">{experimentCoreFields.map(([key,label])=><label key={key}>{label}{key==="workspace_id"||key==="code_repository_workspace_id"?<select value={draft[key]} onChange={(event)=>setDraft({...draft,[key]:event.target.value,...(key==="workspace_id"&&!draft.code_repository_workspace_id?{code_repository_workspace_id:event.target.value}:{})})}><option value="">{key==="workspace_id"?"请选择执行环境":"默认使用执行 Workspace"}</option>{workspaces.map((workspace)=><option key={workspace.id} value={workspace.id}>{workspaceLabel(workspace,dashboard)}{key==="code_repository_workspace_id"&&!workspace.external_code_url?" · 外部 URL 未配置":""}</option>)}</select>:<textarea value={draft[key]} onChange={(event)=>setDraft({...draft,[key]:event.target.value})}/>}</label>)}</div><details className="form-advanced"><summary>补充假设、证据和成功标准（可稍后填写）</summary><div className="domain-form-grid">{experimentAdvancedFields.map(([key,label])=><label key={key}>{label}<textarea value={draft[key]} onChange={(event)=>setDraft({...draft,[key]:event.target.value})}/></label>)}</div><label className="metric-definition-editor">指标定义（每行：id | 名称 | 公式 | 含义 | direction | unit）<textarea placeholder="accuracy | 准确率 | correct / total | 正确样本比例 | higher | ratio" value={metrics} onChange={(event)=>setMetrics(event.target.value)}/><small>确认研究设计前再补齐即可；已有扩展字段会按 id 保留。</small></label></details><div className="analysis-form-actions"><button className="secondary-button" onClick={onCancel}>取消</button><button className="primary-button" disabled={saving||blocked||!draft.title.trim()||!draft.objective.trim()||!draft.workspace_id} onClick={submit}><Save size={14}/>{saving?"保存中…":"保存实验"}</button></div></section>
}

function RunCreateForm({experiment,dashboard,saving,onCancel,onSave}:{experiment:Experiment;dashboard:ExperimentDashboard;saving:boolean;onCancel:()=>void;onSave:(fields:Partial<Run>)=>void}){
 const [draft,setDraft]=useState<Record<string,string>>(()=>Object.fromEntries(runCreateFields.map(([key])=>[key,""])));
 return <section className="experiment-domain-form focused-create-form"><div className="domain-form-head"><div><strong>新建 Run</strong><small>登记一次可追踪运行；研究目标留在 Experiment，这里只写本次目的与验收指标。</small></div><button onClick={onCancel}><X size={14}/></button></div><div className="domain-form-grid">{runCoreFields.map(([key,label])=><label key={key}>{label}<textarea value={draft[key]} onChange={(e)=>setDraft({...draft,[key]:e.target.value})}/></label>)}</div><details className="form-advanced"><summary>分组、数据与环境覆盖（可选）</summary><div className="domain-form-grid">{runAdvancedFields.map(([key,label])=><label key={key}>{label}{key==="group_id"?<select value={draft[key]} onChange={(e)=>setDraft({...draft,[key]:e.target.value})}><option value="">未分组</option>{(experiment.run_groups||[]).map((group)=><option key={group.id} value={group.id}>{group.name}</option>)}</select>:key==="workspace_id"?<select value={draft[key]} onChange={(e)=>setDraft({...draft,[key]:e.target.value})}><option value="">继承实验默认环境（{experiment.workspace_id}）</option>{(dashboard.workspaces||[]).map((workspace)=><option key={workspace.id} value={workspace.id}>{workspaceLabel(workspace,dashboard)}</option>)}</select>:<textarea value={draft[key]} onChange={(e)=>setDraft({...draft,[key]:e.target.value})}/>}</label>)}</div></details><div className="analysis-form-actions"><button className="secondary-button" onClick={onCancel}>取消</button><button className="primary-button" disabled={saving||!draft.id.trim()||!draft.variant.trim()||!draft.research_question.trim()||!draft.purpose.trim()||!draft.metric_plan.trim()} onClick={()=>onSave(draft)}><Save size={14}/>创建运行记录</button></div></section>
}

function TrialPlanPanel({run,saving,onCancel,onPrepare}:{run:Run;saving:boolean;onCancel:()=>void;onPrepare:(input:RunTrialPreparation)=>Promise<void>}){
 const existing=run.trial_plan;const axesText=(existing?.axes||[]).map(axis=>`${axis.name} = ${axis.values.join(", ")}`).join("\n");
 const [mode,setMode]=useState<"ai_planned"|"matrix">(existing?.planning_mode||"ai_planned");const [request,setRequest]=useState(existing?.request||"");const [matrix,setMatrix]=useState(axesText||"variant = baseline, query_permuted\nseed = 1, 2, 3");const [budget,setBudget]=useState(existing?.trial_budget||8);const [concurrency,setConcurrency]=useState(existing?.concurrency||1);const [maxRetries,setMaxRetries]=useState(existing?.max_retries??1);const [localError,setLocalError]=useState("");
 let count=0;try{count=trialCount(parseTrialAxes(matrix))}catch{/* 输入过程中保持 0 */}
 const submit=async()=>{try{if(!request.trim())throw new Error("请说明这组实验要回答什么问题");const input:RunTrialPreparation=mode==="matrix"?{request:request.trim(),planning_mode:"matrix",axes:parseTrialAxes(matrix),trial_budget:count,concurrency,max_retries:maxRetries}:{request:request.trim(),planning_mode:"ai_planned",trial_budget:budget,concurrency,max_retries:maxRetries};setLocalError("");await onPrepare(input)}catch(reason){setLocalError(reason instanceof Error?reason.message:String(reason))}};
 const plannedCount=mode==="matrix"?count:budget;
 return <><TrialCampaignHistory run={run}/><section className="trial-plan-panel"><header><div><small>NEW RUN-LOCAL CAMPAIGN</small><strong>登记下一组参数实验</strong><p>全部 Trial 属于同一个 Run；新组会单独留档，不覆盖上面的历史记录。</p></div><button className="icon-button" onClick={onCancel}><X size={15}/></button></header>{localError&&<div className="detail-error">{localError}</div>}<div className="trial-planning-modes"><button type="button" className={mode==="ai_planned"?"active":""} onClick={()=>setMode("ai_planned")}><Bot size={14}/><span><b>AI 自主规划</b><small>给目标和大致次数，AI 决定具体参数</small></span></button><button type="button" className={mode==="matrix"?"active":""} onClick={()=>setMode("matrix")}><Workflow size={14}/><span><b>手动参数矩阵</b><small>你明确指定每个参数及其取值</small></span></button></div><label>这组实验要回答什么？<textarea value={request} onChange={event=>setRequest(event.target.value)} placeholder={mode==="ai_planned"?"例如：在固定数据和主指标下，规划约 8 次最有信息量的实验，找出影响准确率的关键设置。":"例如：固定数据和模型，比较 baseline / query_permuted，并汇总 3 个 seed。"}/></label>{mode==="matrix"?<label>参数矩阵 <small>每行：参数名 = 值1, 值2；数字和 true/false 会自动识别</small><textarea value={matrix} onChange={event=>setMatrix(event.target.value)} spellCheck={false}/></label>:<label className="trial-budget-field">大致实验次数 <small>这是上限预算；AI 可以少做无信息增益的组合，但必须说明理由</small><input type="number" min="1" max="64" value={budget} onChange={event=>setBudget(Math.max(1,Math.min(64,Number(event.target.value)||1)))}/></label>}<div className="trial-plan-options"><label>并发 Trial<input type="number" min="1" max="8" value={concurrency} onChange={event=>setConcurrency(Number(event.target.value)||1)}/></label><label>单 Trial 自动重试<input type="number" min="0" max="3" value={maxRetries} onChange={event=>setMaxRetries(Number(event.target.value)||0)}/></label><div><small>{mode==="matrix"?"展开结果":"Trial 预算"}</small><strong>{plannedCount||"—"} Trials</strong></div></div><div className="trial-plan-note"><ShieldAlert size={15}/><span>{mode==="ai_planned"?"Steward 会先读取当前 Run、代码与已有结果，再规划最有信息量的参数组合；不会自行改变数据、主指标、对照或 Workspace。":"Steward 会核验真实 launcher 并按矩阵运行；不会静默改变参数。"} 实现或环境故障可在预算内自动修复重试。</span></div><footer><button className="secondary-button" onClick={onCancel} disabled={saving}>取消</button><button className="primary-button" onClick={()=>void submit()} disabled={saving||!plannedCount||!request.trim()}><Workflow size={14}/>{saving?"生成启动指令中…":`保存 Campaign 并生成 Steward 启动指令`}</button></footer></section></>
}

function TrialCampaignHistory({run}:{run:Run}){
 const campaigns=[...(run.trial_campaigns||[])].reverse();
 if(!campaigns.length)return null;
 return <section className="trial-campaign-history"><header><div><small>RUN-LOCAL CAMPAIGNS</small><strong>已登记的参数实验</strong><p>每组都保留当时的问题、参数、Trial 清单与结果；它们共享 Run 身份，但不会覆盖历史记录。</p></div><span>{campaigns.length} 组</span></header><div>{campaigns.map((campaign,index)=>{const plan=campaign.plan;const trials=campaign.manifest?.trials?.length?campaign.manifest.trials:plan.trials;return <details key={campaign.id} open={index===0}><summary><span><b>{campaign.id} · {campaign.request}</b><small>{formatTimestamp(campaign.created_at)} · {plan.planning_mode==="ai_planned"?"AI 规划":"参数矩阵"} · {trials.length||plan.trial_budget||0} Trials · 并发 {plan.concurrency}</small></span><em>{statusLabel(campaign.status)}</em></summary><div className="trial-campaign-body">{plan.axes.length>0&&<section><b>参数轴</b><div className="trial-axis-list">{plan.axes.map(axis=><span key={axis.name}><code>{axis.name}</code> = {axis.values.map(value=>String(value)).join("、")}</span>)}</div></section>}<section><b>Trial 明细</b>{trials.length?<div className="trial-record-list">{trials.map(trial=><article key={trial.id}><strong>{trial.id}</strong><code>{Object.entries(trial.parameters||{}).map(([key,value])=>`${key}=${String(value)}`).join(" · ")||"参数待 Steward 规划"}</code>{"rationale" in trial&&trial.rationale&&<p>{trial.rationale}</p>}{"status" in trial&&<small>{statusLabel(String(trial.status||"planned"))}{typeof trial.attempts==="number"?` · ${trial.attempts} attempts`:""}</small>}</article>)}</div>:<p className="trial-awaiting-plan">尚未生成具体 Trial；Steward 启动后会登记完整参数清单。</p>}</section>{campaign.previous_result&&Object.keys(campaign.previous_result).length>0&&<details><summary>本组开始前的 Run 结果快照</summary><pre><code>{text(campaign.previous_result)}</code></pre></details>}{campaign.result&&Object.keys(campaign.result).length>0&&<details open><summary>本组结果</summary><pre><code>{text(campaign.result)}</code></pre></details>}</div></details>})}</div></section>
}

function EnvironmentAssignment({title,value,dashboard,saving,allowInherit,onCancel,onSave}:{title:string;value:string;dashboard:ExperimentDashboard;saving:boolean;allowInherit:boolean;onCancel:()=>void;onSave:(value:string)=>void}){
 const [selected,setSelected]=useState(value);const selectedWorkspace=dashboard.workspaces?.find(item=>item.id===selected);const selectedServer=dashboard.servers?.find(item=>item.id===selectedWorkspace?.server_id);
 return <section className="environment-assignment"><header><div><small>Execution Environment</small><strong>{title}</strong></div><button className="icon-button" onClick={onCancel} aria-label="关闭环境选择"><X size={16}/></button></header><label>选择 Workspace<select value={selected} onChange={event=>setSelected(event.target.value)}>{allowInherit&&<option value="">继承 Experiment 默认环境</option>}{(dashboard.workspaces||[]).map(workspace=><option key={workspace.id} value={workspace.id}>{workspaceLabel(workspace,dashboard)}</option>)}</select></label><div className="environment-assignment-preview"><Server size={17}/><span><b>{selected?`${selectedWorkspace?.id} · ${selectedWorkspace?.label||"未命名"}`:"继承 Experiment 默认环境"}</b><small>{selected?`${selectedServer?.label||selectedServer?.id||"Server 未绑定"} · ${selectedWorkspace?.remote_repo||"仓库未登记"}`:"Run 不保存覆盖值，始终跟随 Experiment"}</small></span></div><p><ShieldAlert size={14}/>这里只更改环境指派；不会连接 SSH、启动、重启或授权 Run。</p><footer><button className="secondary-button" onClick={onCancel}>保持当前环境</button><button className="primary-button" disabled={saving||(!allowInherit&&!selected)||selected===value} onClick={()=>onSave(selected)}><Save size={14}/>{saving?"保存中…":"确认环境指派"}</button></footer></section>
}

function AiGroupingPanel({experiment,runs,projectPath,saving,onCancel,onApplied}:{experiment:Experiment;runs:Run[];projectPath:string;saving:boolean;onCancel:()=>void;onApplied:()=>Promise<void>}){
 const [prompt,setPrompt]=useState("");const [response,setResponse]=useState("");const [proposal,setProposal]=useState<RunGroupingProposal|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [notice,setNotice]=useState("");
 const impact=useMemo(()=>proposal?previewRunGrouping(proposal,experiment,runs):null,[proposal,experiment,runs]);
 const generate=async()=>{setBusy(true);setError("");try{const result=await previewAiRunGroupingPrompt(projectPath,experiment.id);setPrompt(result.prompt);setNotice("已根据当前 Experiment 与 Run 快照生成约束 Prompt") }catch(reason){setError(reason instanceof Error?reason.message:String(reason))}finally{setBusy(false)}};
 const parse=()=>{try{setProposal(parseRunGroupingProposal(response,experiment.id));setError("");setNotice("已完成本地 schema 校验；应用前请检查影响预览") }catch(reason){setProposal(null);setError(reason instanceof Error?reason.message:String(reason))}};
 const apply=async()=>{if(!proposal||!impact||impact.invalidAssignments.length||impact.unknownRunIds.length)return;setBusy(true);setError("");try{const result=await applyAiRunGrouping(projectPath,experiment,proposal.groups,proposal.assignments);const totals=result.grouping_result.totals;setNotice(`已应用 ${totals.applied||0} 项，后端跳过 ${totals.skipped||0} 项，新增 ${totals.groups_added||0} 个分组`);await onApplied()}catch(reason){setError(reason instanceof ApiError&&reason.reason==="registry_version_conflict"?"Experiment 已变化，请关闭后重新生成建议":reason instanceof Error?reason.message:String(reason))}finally{setBusy(false)}};
 return <section className="ai-grouping-panel"><div className="domain-form-head"><div><strong><Bot size={16}/>AI Run 分组</strong><small>AI 只提出结构化建议；页面预览，后端逐条裁决，绝不自动移动锁定 Run。</small></div><button onClick={onCancel} aria-label="关闭 AI 分组"><X size={16}/></button></div>{error&&<div className="detail-error">{error}</div>}{notice&&<div className="ai-grouping-notice">{notice}</div>}<div className="ai-grouping-grid"><div><label>1. 生成给 AI 的 Prompt<textarea value={prompt} onChange={(event)=>setPrompt(event.target.value)} placeholder="点击生成约束 Prompt"/></label><div className="ai-grouping-actions"><button className="secondary-button" onClick={()=>void generate()} disabled={busy}>{prompt?"刷新当前快照":"生成 Prompt"}</button><button className="secondary-button" disabled={!prompt} onClick={()=>void navigator.clipboard.writeText(prompt)}><Copy size={13}/>复制</button></div><small className="ai-grouping-bridge">旧 Pi 直发入口已移除；复制到独立 AI 会话，或使用对象页的 Herdr 新会话。</small></div><div><label>2. 粘贴 JSON 回复<textarea value={response} onChange={(event)=>{setResponse(event.target.value);setProposal(null)}} placeholder='{"contract":"survey-tool.run-grouping/v1", ...}'/></label><div className="ai-grouping-actions"><button className="primary-button" disabled={!response.trim()} onClick={parse}>解析并预览</button></div></div></div>{impact&&<div className="ai-grouping-impact"><header><div><strong>3. 影响预览</strong><span>可移动 {impact.moves.length} · 锁定跳过 {impact.locked.length} · 未变化 {impact.unchanged.length} · 新组 {impact.newGroups.length}</span></div><button className="primary-button" disabled={saving||busy||Boolean(impact.invalidAssignments.length||impact.unknownRunIds.length)} onClick={()=>void apply()}>明确应用安全项</button></header>{impact.newGroups.length>0&&<div><b>建议新组</b>{impact.newGroups.map((group)=><span key={group.id}><i style={{background:group.color||"#668f89"}}/>{group.name} <small>{group.id} · {group.description||"无说明"}</small></span>)}</div>}{impact.moves.length>0&&<div><b>将移动</b>{impact.moves.map((item)=><span key={item.runId}><code>{item.runId}</code> {item.from||"未分组"} → {item.to||"未分组"}</span>)}</div>}{impact.locked.length>0&&<div className="warning"><b>锁定，后端会跳过</b>{impact.locked.map((item)=><span key={item.runId}><code>{item.runId}</code> {item.from||"未分组"} → {item.to||"未分组"}</span>)}</div>}{(impact.unknownRunIds.length>0||impact.invalidAssignments.length>0)&&<div className="danger"><b>必须修正后才能应用</b>{impact.unknownRunIds.map((id)=><span key={id}>未知 Run：{id}</span>)}{impact.invalidAssignments.map((item)=><span key={item.runId}>{item.runId} 引用未声明组 {item.groupId}</span>)}</div>}</div>}</section>
}

function FolderBoard({experiment,runs,onOpen}:{experiment:Experiment;runs:Run[];onOpen:(id:string)=>void}){
 const groups=[...(experiment.run_groups||[]),{id:"",name:"未分组",description:"尚未分配职责组",color:"#89939b"}];
 return <div className="run-folder-board">{groups.map((group)=>{const rows=runs.filter((run)=>(run.group_id||"")===group.id);if(!rows.length&&group.id==="")return null;return <section key={group.id||"ungrouped" } style={{"--group-color":group.color||"#668f89"} as CSSProperties}><header><Folder size={17}/><div><h3>{group.name}</h3><p>{group.description||"Run responsibility group"}</p></div><span>{rows.length}</span></header><div className="run-folder-cards">{rows.map((run)=><RunCard key={run.id} run={run} onOpen={onOpen}/>)}</div></section>})}</div>
}
function RunCard({run,onOpen}:{run:Run;onOpen:(id:string)=>void}){return <button className="run-folder-card" onClick={()=>onOpen(run.id)}><div><strong>{run.id}</strong>{["pending_review","approved"].includes(run.review_status||"")&&<LockKeyhole size={12}/>}</div><h4>{run.variant||"未命名变体"}</h4><p>{run.purpose||"目的未登记"}</p><small>{statusLabel(run.status)} · {statusLabel(run.review_status)} · {run.workflow_stage||"research_design"}</small><em>{run.metric_plan||run.metric_definition||"指标待补充"}</em><time>创建 {formatTimestamp(run.created)}</time></button>}

function GroupingForm({experiment,runs,saving,onCancel,onSave}:{experiment:Experiment;runs:Run[];saving:boolean;onCancel:()=>void;onSave:(groups:NonNullable<Experiment["run_groups"]>,assignments:Record<string,string>)=>void}){
 const encode=(experiment.run_groups||[]).map((g)=>[g.id,g.name,g.description||"",g.color||""].join("|")).join("\n");
 const [groupText,setGroupText]=useState(encode);const [assignments,setAssignments]=useState<Record<string,string>>(Object.fromEntries(runs.map((run)=>[run.id,run.group_id||""])));const [preview,setPreview]=useState(false);
 const groups=groupText.split("\n").filter(Boolean).map((line)=>{const [id,name,description,color]=line.split("|");return{id:id?.trim(),name:name?.trim(),description:description?.trim(),color:color?.trim()}}).filter((g)=>g.id&&g.name);
 return <section className="experiment-domain-form grouping-form"><div className="domain-form-head"><strong>管理 Run 分组</strong><button onClick={onCancel}><X size={14}/></button></div><label>每行：id | 名称 | 说明 | #颜色<textarea value={groupText} onChange={(e)=>{setGroupText(e.target.value);setPreview(false)}}/></label><div className="group-assignment-list">{runs.map((run)=><label key={run.id}><span>{run.id}{["pending_review","approved"].includes(run.review_status||"")&&<LockKeyhole size={12}/>}</span><select value={assignments[run.id]} onChange={(e)=>{setAssignments({...assignments,[run.id]:e.target.value});setPreview(false)}}><option value="">未分组</option>{groups.map((group)=><option key={group.id} value={group.id}>{group.name}</option>)}</select></label>)}</div>{preview&&<div className="grouping-preview">将保存 {groups.length} 个分组和 {runs.length} 个 Run assignment；锁定 Run 仍由后端最终裁决。</div>}<div className="analysis-form-actions"><button className="secondary-button" onClick={()=>setPreview(true)}>预览</button><button className="primary-button" disabled={!preview||saving} onClick={()=>onSave(groups,assignments)}>确认保存分组</button></div></section>
}

function PipelineBoard({runs,dashboard,onOpen}:{runs:Run[];dashboard:ExperimentDashboard;onOpen:(id:string)=>void}){return <div className="pipeline-v2-board">{lanes.map((lane)=>{const rows=runs.filter((run)=>classifyRun(run,dashboard)===lane);return <section key={lane}><header><strong>{laneLabels[lane]}</strong><span>{rows.length}</span></header><div>{rows.map((run)=><RunCard key={run.id} run={run} onOpen={onOpen}/>)}</div></section>})}</div>}

function StewardMonitor({projectPath,experimentId,dashboard,onOpen}:{projectPath:string;experimentId:string;dashboard:ExperimentDashboard;onOpen:(runId:string)=>void}){
 const [data,setData]=useState<StewardStatusList|null>(null);const [error,setError]=useState("");const [loading,setLoading]=useState(false);const [selected,setSelected]=useState("");const [consoleData,setConsoleData]=useState<StewardConsole|null>(null);
 const adopt=(value:StewardStatusList)=>{setData(value);const eligible=value.items.filter(item=>item.experiment_id===experimentId);setSelected(current=>eligible.some(item=>item.run_id===current)?current:(eligible.find(item=>item.supervisor_active)||eligible[0])?.run_id||"")};
 const refresh=async()=>{setLoading(true);try{adopt(await loadV2Stewards(projectPath));setError("")}catch(reason){setError(reason instanceof Error?reason.message:String(reason))}finally{setLoading(false)}};
 useEffect(()=>{let mounted=true;const poll=()=>loadV2Stewards(projectPath).then(value=>{if(mounted){adopt(value);setError("")}}).catch(reason=>{if(mounted)setError(reason instanceof Error?reason.message:String(reason))});void poll();const timer=window.setInterval(poll,5000);return()=>{mounted=false;window.clearInterval(timer)}},[projectPath,experimentId]);
 useEffect(()=>{setConsoleData(null);if(!selected)return;let mounted=true;const poll=()=>loadV2StewardConsole(projectPath,selected).then(value=>{if(mounted)setConsoleData(value)}).catch(reason=>{if(mounted)setConsoleData({run_id:selected,available:false,connected:false,output:"",reason:reason instanceof Error?reason.message:String(reason),captured_at:"",truncated:false})});void poll();const timer=window.setInterval(poll,2000);return()=>{mounted=false;window.clearInterval(timer)}},[projectPath,selected]);
 const rows=(data?.items||[]).filter(item=>item.experiment_id===experimentId);const current=rows.find(item=>item.run_id===selected);const experiment=current?dashboard.experiments.find(row=>row.id===current.experiment_id):undefined;
 return <section className="steward-monitor"><header><div><small>LIVE HERDR PI AGENT</small><h3>{experimentId} · Steward Agent</h3><p>只显示当前 Experiment 中明确启动的 Run。每个 Run 对应一个独立 Herdr Pi 会话；右侧直接读取该 Agent 的终端。</p></div><button className="secondary-button" onClick={()=>void refresh()} disabled={loading}><RefreshCw size={13}/>{loading?"刷新中…":"刷新"}</button></header>{error&&<div className="detail-error">监控刷新失败：{error}</div>}<div className="steward-console-layout"><aside>{rows.map(item=><button key={item.run_id} className={`${selected===item.run_id?"selected":""} ${item.needs_attention?"attention":""}`} onClick={()=>setSelected(item.run_id)}><span className="steward-pulse"/><span><strong>{item.run_id} · {item.run_label}</strong><small>{item.supervisor.runtime_kind==="herdr_pi"?`Pi ${item.supervisor.agent_status||"working"}`:item.remote_execution_active?"远端执行中":item.supervisor_active?"启动中":item.needs_attention?"启动失败":""}</small></span></button>)}{!rows.length&&<div><Activity size={20}/><strong>当前 Experiment 没有 Steward Agent</strong><small>批准和授权不等于执行；请在 Run 详情明确启动。</small></div>}</aside><div className="steward-cli"><div className="steward-cli-bar"><span/><span/><span/><strong>{current?`${current.run_id} · ${experiment?.title||current.experiment_id}`:"未连接"}</strong><small>{consoleData?.connected?`${consoleData.agent_status||"LIVE"} · ${formatTimestamp(consoleData.captured_at)}`:"OFFLINE"}</small></div><pre aria-label="Steward CLI 输出">{consoleData?.available?(consoleData.output||"（Pi Agent 已启动，尚未产生终端输出）"):current?`${current.needs_attention?"启动失败":"尚未连接 Herdr Pi"}：${current.supervisor.error_class||consoleReason(consoleData?.reason)}\n${current.supervisor.message||"没有进一步错误信息"}`:"从左侧选择一个 Steward Agent。"}</pre><footer><span>{consoleData?.truncated?"输出较长，Herdr 已截断":"最多显示最近 400 行"}</span>{current&&<button onClick={()=>onOpen(current.run_id)}>打开 Run 详情</button>}</footer></div></div><small className="steward-console-note">Pi Agent 负责领取授权、受控启动、定时监控、边界内修复和结果收集；科研结论仍停在 analysis_pending 等待你确认。</small></section>
}

function consoleReason(reason?:string){return ({steward_not_active:"Steward 进程未运行",console_not_attested:"尚未建立受控 tmux",tmux_capture_failed:"tmux 暂时不可读取",agent_not_attested:"Pi Agent 尚未完成 ownership attestation",herdr_agent_unavailable:"Herdr Pi Agent 当前不可读取"} as Record<string,string>)[reason||""]||reason||"等待连接"}

function RunDetail({run,experiment,dashboard,projectPath,saving,error,setError,mutate,onChanged,onBack}:{run:Run;experiment:Experiment;dashboard:ExperimentDashboard;projectPath:string;saving:boolean;error:string;setError:(value:string)=>void;mutate:(work:()=>Promise<unknown>)=>Promise<boolean>;onChanged:()=>Promise<void>;onBack:()=>void}){
 const [editing,setEditing]=useState(false);const [trialOpen,setTrialOpen]=useState(false);const [solidOpen,setSolidOpen]=useState(false);const [solidNote,setSolidNote]=useState(run.evidence_label_note||"");const [failureOpen,setFailureOpen]=useState(false);const [failureReason,setFailureReason]=useState("");const [correctionOpen,setCorrectionOpen]=useState(false);const [correctionTarget,setCorrectionTarget]=useState<"running"|"analysis_pending">("running");const [correctionReason,setCorrectionReason]=useState("");const [correctionEvidence,setCorrectionEvidence]=useState("");const [assigningEnvironment,setAssigningEnvironment]=useState(false);const [environmentOpen,setEnvironmentOpen]=useState(false);const [aiOpen,setAiOpen]=useState(false);const [aiTask,setAiTask]=useState<DiscussionTask>("question");const [steward,setSteward]=useState<StewardStatus|null>(null);const [stewardCommand,setStewardCommand]=useState("");const [reviewOpen,setReviewOpen]=useState(false);const [requirements,setRequirements]=useState("");const [questions,setQuestions]=useState("");const [authorizationNote,setAuthorizationNote]=useState("");const stage=steward?.workflow_stage||run.workflow_stage||"code_planning";const locked=["running","analysis_pending","completed"].includes(stage);const trialPlanningLocked=Boolean(steward?.remote_execution_active);
 const lastWorkflowSync=useRef("");
 const [draft,setDraft]=useState<Record<string,string>>(()=>Object.fromEntries(runEditKeys.map((key)=>[key,text(run[key])])));
 const save=async()=>{const fields:Partial<Run>={};try{runEditKeys.forEach((key)=>{(fields as Record<string,unknown>)[key]=jsonKeys.has(key)&&draft[key].trim()?JSON.parse(draft[key]):draft[key]})}catch(reason){setError(`JSON 字段格式错误：${reason instanceof Error?reason.message:String(reason)}`);return}if(await mutate(()=>updateV2Run(projectPath,run.id,run.updated||"",fields)))setEditing(false)};
 const prepareSteward=async(target=run)=>{const resumeExisting=steward?.dispatch?.status==="running";const retrySameApprovedAttempt=steward?.dispatch?.status==="failed"&&target.workflow_stage==="failed"&&target.review_status==="approved"&&Boolean(target.execution_authorized_at);const result=retrySameApprovedAttempt&&!resumeExisting?await restartV2FailedRunSteward(projectPath,target):await startV2RunSteward(projectPath,target);setStewardCommand(result.handoff_command);try{await navigator.clipboard.writeText(result.handoff_command)}catch{/* 命令仍显示在页面供手工复制 */}return result};
 const startBackground=(target=run)=>mutate(()=>prepareSteward(target));
 const forceRestartSteward=async()=>{if(!window.confirm("强制更换 Steward 控制会话？\n\n旧 Pi 将立即失去 execution lease；远端 tmux 和当前实验不会被停止、复制或重新启动。新 Pi 只会 reattach 同一个 execution attempt。"))return;await mutate(async()=>{const result=await forceRestartV2RunSteward(projectPath,run);setStewardCommand(result.handoff_command);try{await navigator.clipboard.writeText(result.handoff_command)}catch{/* 页面仍显示命令 */}return result})};
 const markAttemptFailed=async()=>{if(await mutate(()=>markV2StewardAttemptFailed(projectPath,run,failureReason))){setFailureOpen(false);setFailureReason("")}};
 const correctFailedStatus=async()=>{if(await mutate(()=>correctV2FailedRunStatus(projectPath,run,correctionTarget,correctionReason,correctionEvidence))){setCorrectionOpen(false);setCorrectionReason("");setCorrectionEvidence("");await onChanged()}};
 const review=async(action:"submit"|"request_changes"|"approve"|"authorize_execution")=>{const work=action==="authorize_execution"?async()=>{const authorized=await reviewV2Run(projectPath,run,action,{authorization_note:authorizationNote});try{return await prepareSteward(authorized.run)}catch(reason){await onChanged();throw new Error(`授权已保存，但 Steward 启动命令未生成：${reason instanceof Error?reason.message:String(reason)}`)}}:()=>reviewV2Run(projectPath,run,action,{requirements,questions,authorization_note:authorizationNote});if(await mutate(work))setReviewOpen(false)};
 const workflow=async(action:RunWorkflowAction)=>{const resultFields=action==="finalize-results"?{result_analysis:run.result_analysis,key_results:run.key_results,metric_observations:run.metric_observations,limitations:run.limitations,artifacts:run.artifacts}:{};await mutate(()=>transitionV2RunWorkflow(projectPath,run,action,resultFields))};
 const saveSolid=async(label:"solid"|"")=>{if(await mutate(()=>setV2RunEvidenceLabel(projectPath,run,label,solidNote))){setSolidOpen(false);if(!label)setSolidNote("")}};
 useEffect(()=>{let active=true;let timer:number|undefined;const refresh=()=>loadV2RunSteward(projectPath,run.id).then(value=>{if(!active)return;setSteward(value);const canonicalStage=run.workflow_stage||run.status||"";if(value.workflow_stage&&value.workflow_stage!==canonicalStage&&lastWorkflowSync.current!==value.workflow_stage){lastWorkflowSync.current=value.workflow_stage;void onChanged()}else if(value.workflow_stage===canonicalStage)lastWorkflowSync.current=""}).catch(()=>undefined);void refresh();if(stage==="running"||Boolean(run.execution_authorized_at))timer=window.setInterval(refresh,5000);return()=>{active=false;if(timer)window.clearInterval(timer)}},[projectPath,run.id,run.execution_authorized_at,run.workflow_stage,run.status,stage]);
 if(editing)return <div className="run-detail-page"><button className="back-button" onClick={()=>setEditing(false)}><ChevronLeft size={14}/>返回 Run 阅读态</button>{error&&<div className="detail-error">{error}</div>}<section className="run-record-form"><h2>编辑完整研究记录</h2>{runSections.map(([title,fields])=><details open key={title}><summary>{title}</summary><div>{fields.map(([key,label])=><label key={key}>{label}{key==="workspace_id"?<select value={draft[key]} onChange={e=>setDraft({...draft,[key]:e.target.value})}><option value="">继承 Experiment 默认环境（{experiment.workspace_id}）</option>{(dashboard.workspaces||[]).map(item=><option key={item.id} value={item.id}>{workspaceLabel(item,dashboard)}</option>)}</select>:<textarea placeholder={key==="implementation_ref"?'{"package":"...","entrypoint":"...","config":"..."}':undefined} value={draft[key]} onChange={(e)=>setDraft({...draft,[key]:e.target.value})}/>} {key==="implementation_ref"&&<small>JSON 对象；用于后端 architecture/workspace gate，不接受自由文本。</small>}</label>)}</div></details>)}<div className="analysis-form-actions"><button className="secondary-button" onClick={()=>setEditing(false)}>取消</button><button className="primary-button" onClick={()=>void save()} disabled={saving}><Save size={14}/>{saving?"保存中…":"保存研究记录"}</button></div></section></div>;
 const workspace=dashboard.workspaces?.find((item)=>item.id===(run.workspace_id||experiment.workspace_id));const boundServer=dashboard.servers?.find(item=>item.id===workspace?.server_id);const isolation=workspace?.execution_isolation;const dispatch=dashboard.execution_outbox?.items?.find((item)=>item.run_id===run.id);const journey=describeRunJourney({...run,workflow_stage:stage,status:stage});const journeyIndex=runJourneySteps.findIndex(item=>item.id===journey.current);
 const staleStewardController=Boolean(steward?.supervisor_active&&!steward.remote_execution_active&&steward.supervisor.dispatch_id&&steward.dispatch?.dispatch_id&&steward.supervisor.dispatch_id!==steward.dispatch.dispatch_id);
 const manualFailureEligible=["queued","delivered","claimed","acknowledged","running"].includes(String(steward?.dispatch?.status||dispatch?.status||""));
 const revisedFailedRunReady=stage==="failed"&&run.review_status==="changes_requested"&&!run.execution_authorized_at;
 return <div className="run-detail-page">{aiOpen&&<AiDiscussionPanel targetType="run" targetId={run.id} targetLabel={`${run.id} · ${run.variant||"Run"}`} projectPath={projectPath} initialTask={aiTask} onClose={()=>setAiOpen(false)}/>} {environmentOpen&&workspace&&<EnvironmentBindingsPanel projectPath={projectPath} initialWorkspaceId={workspace.id} onChanged={onChanged} onClose={()=>setEnvironmentOpen(false)}/>}<button className="back-button" onClick={onBack}><ChevronLeft size={14}/>返回 {experiment.id}</button>{error&&<div className="detail-error">{error}</div>}<header className="run-detail-header"><div><div className="experiment-meta"><code>{run.id}</code><span>{statusLabel(run.review_status)}</span><span>{stage}</span>{run.evidence_label==="solid"&&<span className="solid-evidence-badge">SOLID EVIDENCE</span>}</div><h1>{run.variant||run.id}</h1><div className="run-timestamps"><span>创建：{formatTimestamp(run.created)}</span><span>最后更新：{formatTimestamp(run.updated)}</span></div><p>{run.purpose||"Run 目的尚未登记"}</p></div><div className="experiment-header-actions"><button className="primary-button" onClick={()=>{setAiTask("run_implementation");setAiOpen(true)}}><Bot size={14}/>实现代码</button><button className="secondary-button" onClick={()=>setTrialOpen(true)} disabled={trialPlanningLocked}><Workflow size={14}/>参数批量实验</button>{stage==="failed"&&<><button className="secondary-button" onClick={()=>setCorrectionOpen(!correctionOpen)}><RefreshCw size={14}/>修正状态</button><button className="secondary-button" onClick={()=>{setAiTask("code_edit");setAiOpen(true)}}>诊断失败</button></>}<button className="secondary-button" onClick={()=>{setAiTask("question");setAiOpen(true)}}><MessagesSquare size={14}/>讨论</button><button className={run.evidence_label==="solid"?"solid-evidence-button active":"secondary-button"} onClick={()=>setSolidOpen(!solidOpen)}><CheckCircle2 size={14}/>{run.evidence_label==="solid"?"Solid 证据":"标记 Solid"}</button><button className="secondary-button" onClick={()=>setEditing(true)} disabled={locked}><Pencil size={14}/>编辑研究记录</button></div></header>{solidOpen&&<section className="solid-evidence-panel"><div><small>HUMAN EVIDENCE LABEL</small><strong>{run.evidence_label==="solid"?"此 Run 已标记为 Solid":"把此 Run 标记为 Solid"}</strong><p>AI 讨论会获得此 Run 的真实指标、结果分析、局限和 Claim 边界。该标签是人工证据评级，不会改变审核、执行状态或 Claim verdict。</p></div><label>判断说明（可选）<textarea value={solidNote} onChange={event=>setSolidNote(event.target.value)} placeholder="例如：三个 seed 一致，主指标和完整性检查均通过"/></label><div><button className="secondary-button" onClick={()=>setSolidOpen(false)}>取消</button>{run.evidence_label==="solid"&&<button className="secondary-button" disabled={saving} onClick={()=>void saveSolid("")}>取消 Solid 标签</button>}<button className="primary-button" disabled={saving} onClick={()=>void saveSolid("solid")}><CheckCircle2 size={14}/>{saving?"保存中…":"保存 Solid 标签"}</button></div></section>}{trialOpen&&<TrialPlanPanel run={run} saving={saving} onCancel={()=>setTrialOpen(false)} onPrepare={async(input)=>{const ok=await mutate(async()=>{const result=await prepareV2RunTrials(projectPath,run,input);setStewardCommand(result.handoff_command);try{await navigator.clipboard.writeText(result.handoff_command)}catch{/* 页面仍显示命令 */}return result});if(ok)setTrialOpen(false)}}/>}<section className="run-journey"><div className="run-journey-copy"><small>现在只做这一件事</small><strong>{journey.title}</strong><p>{journey.guidance}</p></div><ol>{runJourneySteps.map((item,index)=><li key={item.id} className={index<journeyIndex?"done":index===journeyIndex?"current":""}><span>{index<journeyIndex?"✓":index+1}</span>{item.label}</li>)}</ol></section>{steward?.canonical_stage_stale&&<div className="run-lock-banner"><ShieldAlert size={16}/>Run 文件仍记录为 {run.workflow_stage||run.status}，但当前关联 execution attempt 正在由 Steward 管理；完成或失败时会由持 lease 的终态操作自动收敛，浏览器不会重复改写。</div>}{locked&&<div className="run-lock-banner"><LockKeyhole size={16}/>Run 处于 {run.review_status}，普通研究字段已锁定；需先由审核动作退回修改。</div>}{assigningEnvironment&&<EnvironmentAssignment title="Run 环境指派" value={run.workspace_id||""} dashboard={dashboard} saving={saving} allowInherit onCancel={()=>setAssigningEnvironment(false)} onSave={(workspaceId)=>void mutate(async()=>{const result=await updateV2Run(projectPath,run.id,run.updated||"",{workspace_id:workspaceId});setAssigningEnvironment(false);return result})}/>}<section className={`run-steward-card ${steward?.remote_execution_active?"active":steward?.needs_attention?"attention":""}`}><div><small>RUN EXECUTION · {steward?.remote_tmux_observed?"REMOTE TMUX OBSERVED":steward?.remote_execution_active?"RUN ATTEMPT ACTIVE":steward?.supervisor_active?"LOCAL STEWARD STARTING":"NOT RUNNING"}</small><strong>{steward?.supervisor.phase==="analysis_pending"?"运行证据已收集，等待人工分析":steward?.remote_tmux_observed?"最近一次受控检查确认 tmux 存活":steward?.remote_execution_active?"远端启动已记录，Steward 正在管理本次 attempt":steward?.state_conflict?"执行记录冲突：running 证据不属于当前 Run attempt":staleStewardController?"旧 Steward 标记与当前 attempt 不一致，可强制新建":steward?.needs_attention?`Steward 启动失败：${steward.supervisor.error_class||"需要处理"}`:steward?.supervisor_active?"Steward 子进程已启动，远端 Run 尚未确认":steward?.can_resume?"后台监督中断，可安全恢复":run.execution_authorized_at?"只有授权记录，Run 尚未执行":run.review_status==="approved"?"Run 已批准，但尚未授权和执行":"Run 尚未批准"}</strong><p>{steward?.remote_tmux_observed?`最近观测：${formatTimestamp(steward.remote_observed_at)}。${steward.supervisor.message||""}`:steward?.supervisor.message||"启动证据只说明 tmux 曾成功创建；只有 Steward 的后续 status 观测才能说明它仍存活。批准或授权本身都不会占用 GPU。"}</p><span>审核：{run.review_status||"draft"} · 授权：{run.execution_authorized_at?"有":"无"} · Outbox：{steward?.dispatch?.status||dispatch?.status||"无"} · tmux 最近观测：{steward?.remote_tmux_observed?"存活":"无新鲜证据"}</span></div>{revisedFailedRunReady&&<button className="primary-button" disabled={saving} onClick={()=>void startBackground()}>{saving?"授权中…":"批准当前修订并交给 Steward 重跑"}</button>}{run.execution_authorized_at&&(!steward?.supervisor_active||staleStewardController)&&(stage==="failed"||steward?.can_start||steward?.can_resume||steward?.needs_attention||staleStewardController)&&<button className="primary-button" disabled={saving||Boolean(steward?.resume_waiting)} onClick={()=>void startBackground()}>{saving?"生成中…":staleStewardController?"强制新建 Steward（复制命令）":steward?.resume_waiting?`等待旧 lease 到期（${formatTimestamp(steward.resume_available_at)}）`:steward?.can_resume?"重新接管 Steward（复制命令）":stage==="failed"||steward?.needs_attention?"重新启动 Steward（复制命令）":stewardCommand?"重新复制启动命令":"复制 Steward 启动命令"}</button>}{steward?.dispatch?.status==="running"&&<button className="secondary-button" disabled={saving} onClick={()=>void forceRestartSteward()}>强制更换 Steward</button>}{manualFailureEligible&&<button className="secondary-button failure-decision-button" disabled={saving} onClick={()=>setFailureOpen(true)}><CircleAlert size={14}/>判断为失败</button>}</section>{failureOpen&&<section className="run-failure-decision"><div><small>人工裁决当前 execution attempt</small><strong>是否确认本次执行已经失败？</strong><p>这会把当前 attempt 记为失败并开放重新启动，但不会连接 SSH、停止 tmux 或终止远端进程。若实验可能仍在运行，请先核对监控。</p></div><label>判断依据<textarea value={failureReason} onChange={event=>setFailureReason(event.target.value)} placeholder="例如：Steward 已退出，远端 tmux 不存在，且日志在启动前终止。"/></label><footer><button className="secondary-button" onClick={()=>setFailureOpen(false)} disabled={saving}>保留当前状态</button><button className="primary-button danger" onClick={()=>void markAttemptFailed()} disabled={saving||!failureReason.trim()}>{saving?"记录中…":"确认本次执行失败"}</button></footer></section>}{correctionOpen&&stage==="failed"&&<section className="run-status-correction"><header><div><small>人工修正误判</small><strong>修正当前 execution attempt 的状态</strong><p>修正只更新同一个 attempt 的可变状态，不会删除原失败记录，也不会启动、停止或复制远端进程。</p></div></header><div className="run-status-correction-options"><label className={correctionTarget==="running"?"selected":""}><input type="radio" name="correction-target" checked={correctionTarget==="running"} onChange={()=>setCorrectionTarget("running")}/><span><b>恢复为运行中</b><small>仅适用于远端 tmux 实际仍在运行。保存后需要重新接管同一个 Steward attempt。</small></span></label><label className={correctionTarget==="analysis_pending"?"selected":""}><input type="radio" name="correction-target" checked={correctionTarget==="analysis_pending"} onChange={()=>setCorrectionTarget("analysis_pending")}/><span><b>转入待分析</b><small>适用于程序实际已结束；随后仍需人工检查指标并确认结果。</small></span></label></div><label>误判修正依据<textarea value={correctionReason} onChange={event=>setCorrectionReason(event.target.value)} placeholder="例如：远端 tmux 和日志确认任务仍在运行，原失败来自 Steward 连接中断。"/></label>{correctionTarget==="analysis_pending"&&<label>执行完成证据<textarea value={correctionEvidence} onChange={event=>setCorrectionEvidence(event.target.value)} placeholder="例如：日志显示 exit 0；结果文件位于 artifacts/R-001/metrics.json。"/></label>}<footer><button className="secondary-button" onClick={()=>setCorrectionOpen(false)} disabled={saving}>取消</button><button className="primary-button" onClick={()=>void correctFailedStatus()} disabled={saving||!correctionReason.trim()||(correctionTarget==="analysis_pending"&&!correctionEvidence.trim())}>{saving?"修正中…":"确认修正状态"}</button></footer></section>}{stewardCommand&&<div className="ai-herdr-handoff"><strong>Steward 启动命令已生成并尝试复制</strong><p>请在一个独立的 Herdr 本地终端运行。浏览器没有启动 Agent、领取 lease 或连接远端。</p><code>{stewardCommand}</code><button className="secondary-button" onClick={()=>void navigator.clipboard.writeText(stewardCommand)}><Copy size={13}/>复制命令</button></div>}<details className="run-technical-details"><summary>执行环境与技术诊断</summary><section className="managed-run-readiness"><strong>Managed execution</strong><span>{isolation?.mode==="bubblewrap"&&isolation.required?`配置就绪（bubblewrap · network ${isolation.network}）`:`Blocked：Workspace ${workspace?.id||"未绑定"} 尚未配置必需的 bubblewrap isolation`}</span><small>Server：{boundServer?.label||boundServer?.id||"未绑定"} / {boundServer?.ssh_host||"无 ssh_host"}；repo：{workspace?.remote_repo||"未登记"}</small><small>Default deny write：开启；未列入 allowed_write_roots 一律拒绝写。重点 forbidden：{workspace?.environment_policy?.forbidden_paths?.join("、")||"未登记"}</small><small>数据绑定：{workspace?.dataset_bindings?.length?(workspace.dataset_bindings.map(item=>`${item.label||item.id} (${item.mode}${item.required?"/required":""})`).join("；")):"无"}</small>{workspace?.pending_rule_draft&&<div className="pending-rule-callout"><ShieldAlert size={16}/><span><b>首次执行准备已生成规则草稿，当前 Run 被安全阻止</b><small>请检查、应用并保存 Workspace 规则；若结构化策略发生变化，需要重新授权执行。</small></span><button className="primary-button" onClick={()=>setEnvironmentOpen(true)}>打开 Workspace 规则</button></div>}<small>绑定变化不会启动或重启任务，并会使既有授权快照失效。Steward 只消费一次现有授权，不改变审核或 Claim。</small></section><AutomationPolicyPanel run={run} saving={saving} onSave={(policy)=>void mutate(()=>updateV2Run(projectPath,run.id,run.updated||"",{automation_policy:policy}))}/></details><ReviewPanel run={run} workflowStage={stage} reviewOpen={reviewOpen} setReviewOpen={setReviewOpen} requirements={requirements} setRequirements={setRequirements} questions={questions} setQuestions={setQuestions} authorizationNote={authorizationNote} setAuthorizationNote={setAuthorizationNote} saving={saving} review={review} workflow={workflow} startSteward={()=>startBackground(run)}/><div className="run-record-sections">{runSections.map(([title,fields])=><section key={title}><h2>{title}</h2><div>{fields.map(([key,label])=><article key={key}><small>{label}</small>{typeof run[key]==="string"?<MarkdownContent>{String(run[key]||"尚未填写")}</MarkdownContent>:<pre><code>{text(run[key])||"尚未填写"}</code></pre>}</article>)}</div></section>)}</div></div>
}

function AutomationPolicyPanel({run,saving,onSave}:{run:Run;saving:boolean;onSave:(policy:NonNullable<Run["automation_policy"]>)=>void}){
 const current=run.automation_policy||{mode:"off" as const,allowed_code_roots:[],test_commands:[],max_repairs:0,time_budget_minutes:30,auto_rerun:false,install_declared_dependencies:false,dependency_files:[]};const [mode,setMode]=useState(current.mode);const [roots,setRoots]=useState(current.allowed_code_roots.join("\n"));const [tests,setTests]=useState(current.test_commands.join("\n"));const [maxRepairs,setMaxRepairs]=useState(current.max_repairs);const [budget,setBudget]=useState(current.time_budget_minutes);const [autoRerun,setAutoRerun]=useState(current.auto_rerun);const [installDeps,setInstallDeps]=useState(current.install_declared_dependencies);const [dependencyFiles,setDependencyFiles]=useState(current.dependency_files.join("\n"));const [open,setOpen]=useState(false);
 const save=()=>onSave({mode,allowed_code_roots:roots.split("\n").map(x=>x.trim()).filter(Boolean),test_commands:tests.split("\n").map(x=>x.trim()).filter(Boolean),max_repairs:mode==="off"?0:maxRepairs,time_budget_minutes:budget,auto_rerun:mode!=="off"&&autoRerun,install_declared_dependencies:mode!=="off"&&installDeps,dependency_files:dependencyFiles.split("\n").map(x=>x.trim()).filter(Boolean)});
 return <section className="run-automation-panel"><header><div><strong>运行出错时怎么办</strong><small>{mode==="off"?"只记录失败，不自动修复。":mode==="careful"?"谨慎修复：只在指定代码目录内修复，测试通过后再重跑。":"积极修复：增加修复次数和时间预算，但不改变研究方案或环境。"}</small></div><button className="secondary-button" onClick={()=>setOpen(!open)}>{open?"收起设置":"配置自动修复"}</button></header>{open&&<div className="run-automation-form"><label>自动修复<select value={mode} onChange={e=>setMode(e.target.value as "off"|"careful"|"active")}><option value="off">关闭</option><option value="careful">谨慎自动修复（推荐）</option><option value="active">积极自动修复</option></select></label><label>允许修改的代码目录（每行绝对路径）<textarea value={roots} onChange={e=>setRoots(e.target.value)} placeholder="/home/remote/project/src"/></label><label>修复后必须通过的测试（每行一条）<textarea value={tests} onChange={e=>setTests(e.target.value)} placeholder="pytest tests/e008 -q"/></label><div className="run-automation-numbers"><label>最多自动修复次数<input type="number" min={0} max={10} value={maxRepairs} onChange={e=>setMaxRepairs(Math.max(0,Math.min(10,Number(e.target.value)||0)))} /></label><label>最多占用时间（分钟）<input type="number" min={1} max={240} value={budget} onChange={e=>setBudget(Math.max(1,Math.min(240,Number(e.target.value)||1)))} /></label></div><label className="run-automation-check"><input type="checkbox" checked={autoRerun} onChange={e=>setAutoRerun(e.target.checked)} />测试通过后自动重新运行</label><label className="run-automation-check"><input type="checkbox" checked={installDeps} onChange={e=>setInstallDeps(e.target.checked)} />允许安装依赖文件中已声明的依赖</label>{installDeps&&<label>依赖文件（每行一个路径）<textarea value={dependencyFiles} onChange={e=>setDependencyFiles(e.target.value)} placeholder="requirements.txt"/></label>}<p>自动修复不能修改研究问题、数据、指标、对照、Workspace、Server 或审批状态；不能创建替代 Conda 环境或使用旧环境路径；策略改变后需要重新授权。</p><button className="primary-button" onClick={save} disabled={saving}>{saving?"保存中…":"保存自动修复设置"}</button></div>}</section>
}

function ReviewPanel({run,workflowStage,reviewOpen,setReviewOpen,requirements,setRequirements,questions,setQuestions,authorizationNote,setAuthorizationNote,saving,review,workflow,startSteward}:{run:Run;workflowStage?:string;reviewOpen:boolean;setReviewOpen:(v:boolean)=>void;requirements:string;setRequirements:(v:string)=>void;questions:string;setQuestions:(v:string)=>void;authorizationNote:string;setAuthorizationNote:(v:string)=>void;saving:boolean;review:(action:"submit"|"request_changes"|"approve"|"authorize_execution")=>Promise<void>;workflow:(action:RunWorkflowAction)=>Promise<void>;startSteward:()=>Promise<unknown>}){
 const isV2=run.workflow_version===2;const isLegacy=!isV2&&!run.review_status&&!["draft","planned"].includes(run.status||"draft");const status=isLegacy?"legacy":run.review_status||"draft";const stage=workflowStage||run.workflow_stage||(isV2?"research_design":"legacy");
 const stageHelp:Record<string,string>={research_design:"先确认 purpose/research_question、metric_plan；Experiment 指标注册表可后续补充。",code_planning:"补齐架构说明、command 与 Workspace；implementation_ref 仅用于登记主仓库中已有入口，可留空。含占位符的 command 将由 Pi 在 Steward 启动前解析。",ready_for_review:"研究设计和代码方案已就绪，可以提交人工审核。",awaiting_review:"等待人工审核；批准不等于执行。",ready_to_run:"审核已通过；执行授权仍与实际执行分离。",running:"执行由既有 Outbox/agent lifecycle 管理，UI 不提供假启动。",analysis_pending:"执行证据已完成；补齐结果分析后由人工确认最终结果。",completed:"结果已由科研 lifecycle 完成。",failed:"本次 execution attempt 已失败；使用上方“重新启动 Steward”可沿用未变化的 approved spec 建立新 attempt，无需退回研究设计。"};
 if(isV2&&!['running','analysis_pending','completed','failed'].includes(stage))return <section className="run-review-panel"><div className="run-review-summary"><Bot size={18}/><span><strong>两步流程：实现 → Steward 运行</strong><small>先用页面顶部“实现代码”让 Pi 完成并核验实现。准备好后直接交给 Steward；不再提交审核、批准和单独授权。</small></span></div><div className="run-review-sections"><div className="run-review-section"><small>当前实现</small><p>{run.git_commit?`已登记 commit ${run.git_commit}`:"尚未登记实现 commit；Pi 可在启动前补齐实现与真实命令。"}</p><p>implementation_ref 的 Shell launcher 可以为空；Managed executor 会生成受控 launcher。</p></div><div className="run-review-section run-authorization-section"><small>运行</small>{run.execution_authorized_at?<span className="authorized"><CheckCircle2 size={13}/>当前快照已交给 Steward；使用上方运行卡片复制启动命令</span>:<button className="authorize" onClick={()=>void startSteward()} disabled={saving}>{saving?"准备中…":"交给 Steward"}</button>}</div></div></section>;
 if(isV2&&stage==="failed"&&status==="approved")return <section className="run-review-panel"><div className="run-review-summary"><ShieldAlert size={18}/><span><strong>本次执行尝试失败，研究方案仍保持批准</strong><small>{stageHelp.failed}</small></span></div><div className="run-review-sections"><div className="run-review-section"><small>方案不变</small><p>若只是修复实现错误，可直接使用上方“重新启动 Steward”，继续沿用当前 approved spec。</p></div><div className="run-review-section run-authorization-section"><small>需要改变方案或名单</small><button className="secondary-button" onClick={()=>setReviewOpen(true)} disabled={saving}>退回修改当前 Run</button></div></div>{reviewOpen&&<div className="review-change-form"><label>本轮必须修改的内容<textarea value={requirements} onChange={(e)=>setRequirements(e.target.value)} placeholder="例如：替换为 R-006 actual Top3/Top5，并增加运行前哈希和名单精确匹配断言。"/></label><label>需要 Steward 回答的问题（可选）<textarea value={questions} onChange={(e)=>setQuestions(e.target.value)}/></label><div><button onClick={()=>setReviewOpen(false)}>取消</button><button onClick={()=>void review("request_changes")} disabled={saving||(!requirements.trim()&&!questions.trim())}>确认退回修改</button></div></div>}</section>;
 if(isV2&&stage==="failed"&&status==="changes_requested")return <section className="run-review-panel"><div className="run-review-summary"><RefreshCw size={18}/><span><strong>首轮结果不满意，当前 Run 已开放修订</strong><small>旧 attempt 和旧 approved spec 均已保留。完善当前研究记录或代码方案后，使用上方“批准当前修订并交给 Steward 重跑”，系统会冻结新快照、创建新授权和独立 attempt。</small></span></div><div className="run-review-sections"><div className="run-review-section"><small>本轮修订要求</small><p>{run.review_requirements||"请登记本轮需要改变的方案或实现。"}</p></div><div className="run-review-section run-authorization-section"><small>重跑边界</small><span className="authorization-waiting">Steward 只能按点击授权时的当前修订快照修改与执行；不会复用旧批准快照。</span></div></div></section>;
 return <section className="run-review-panel"><div className="run-review-summary"><ShieldAlert size={18}/><span><strong>{isV2?`科研 Workflow · ${stage}`:isLegacy?"历史 Run · 只读记录":"Legacy 草稿审核"}</strong><small>{isV2?(stageHelp[stage]||"当前阶段没有可用的普通 UI 动作。"):isLegacy?"该 Run 在 workflow v2 启用前已运行或结束，不能补做审核；如需再次实验，请基于它创建新的 workflow v2 Run。":"迁移期草稿仍可沿用旧审核语义；批准不代表执行。"}</small></span></div>{status==="changes_requested"&&<div className="review-requirements"><p><b>补充要求：</b>{run.review_requirements||"未登记"}</p><p><b>审核问题：</b>{run.review_questions||"未登记"}</p></div>}<div className="run-review-sections"><div className="run-review-section"><small>审核动作</small><div className="run-review-actions">{isV2&&stage==="research_design"&&<button onClick={()=>void workflow("confirm-design")} disabled={saving}>确认研究设计</button>}{isV2&&stage==="code_planning"&&<button onClick={()=>void workflow("implementation-ready")} disabled={saving}>代码方案已准备</button>}{((isV2&&stage==="ready_for_review")||!isV2)&&(status==="draft"||status==="changes_requested")&&<button onClick={()=>void review("submit")} disabled={saving}>{status==="changes_requested"?"重新提交审核":"提交审核"}</button>}{((isV2&&stage==="awaiting_review")||!isV2)&&status==="pending_review"&&<><button onClick={()=>void review("approve")} disabled={saving}><CheckCircle2 size={13}/>批准 Run（不执行）</button><button onClick={()=>setReviewOpen(true)} disabled={saving}>退回修改</button></>}{isV2&&["code_planning","ready_for_review","awaiting_review","ready_to_run"].includes(stage)&&<button className="secondary-button" onClick={()=>void workflow("reopen-design")} disabled={saving}>重新打开研究设计</button>}{isV2&&stage==="analysis_pending"&&<><button onClick={()=>void workflow("finalize-results")} disabled={saving}>确认并完成结果</button><button className="secondary-button" onClick={()=>void workflow("mark-failed")} disabled={saving}>结果不满意，修改后重跑</button></>} {isV2&&stage==="running"&&<span className="authorization-waiting">运行终态由持 lease 的 Steward 写入；浏览器不能绕过 Outbox 标记失败。</span>}</div></div><div className="run-review-section run-authorization-section"><small>执行授权</small><div className="run-review-actions">{((isV2&&stage==="ready_to_run")||!isV2)&&status==="approved"&&!run.execution_authorized_at&&<><input placeholder="授权说明" value={authorizationNote} onChange={(e)=>setAuthorizationNote(e.target.value)}/><button className="authorize" onClick={()=>void review("authorize_execution")} disabled={saving}>授权并交给 Steward 后台运行</button></>}{((isV2&&stage==="ready_to_run")||!isV2)&&status==="approved"&&run.execution_authorized_at&&<><span className="authorized"><LockKeyhole size={13}/>已有执行授权</span><button className="authorize" disabled={saving} onClick={()=>void review("authorize_execution")}>重新授权当前配置并准备 Steward</button><small>修正路径或旧派发取消后使用；为当前配置建立新授权，不复用旧派发，也不直接启动远端任务。</small></>}{!((isV2&&stage==="ready_to_run")||!isV2)&&<span className="authorization-waiting">批准后才可建立一次后台执行授权</span>}</div></div></div>{reviewOpen&&((isV2&&stage==="awaiting_review")||!isV2)&&status==="pending_review"&&<div className="review-change-form"><label>补充要求<textarea value={requirements} onChange={(e)=>setRequirements(e.target.value)}/></label><label>审核问题<textarea value={questions} onChange={(e)=>setQuestions(e.target.value)}/></label><div><button onClick={()=>setReviewOpen(false)}>取消</button><button onClick={()=>void review("request_changes")} disabled={saving||(!requirements.trim()&&!questions.trim())}>确认退回</button></div></div>}</section>
}
